def find_interesting_array(n, m, constraints):
    # Initialize the array with zeros
    a = [0] * n

    # Apply each constraint to the array
    for li, ri, qi in constraints:
        for i in range(li - 1, ri):
            a[i] |= qi

    # Check if the array satisfies all constraints
    for li, ri, qi in constraints:
        if not all((a[i] & qi) == qi for i in range(li - 1, ri)):
            return "NO"

    return "YES\n" + " ".join(map(str, a))

